461	  public reply(
462	    response: TRawResponse | TReply,
463	    body: any,
464	    statusCode?: number,
465	  ) {
466	    const fastifyReply: TReply = this.isNativeResponse(response)
467	      ? new Reply(
468	          response,
469	          {
470	            [kRouteContext]: {
471	              preSerialization: null,
472	              preValidation: [],
473	              preHandler: [],
474	              onSend: [],
475	              onError: [],
476	            },
477	          },
478	          {},
479	        )
480	      : response;
481	
482	    if (!isNil(statusCode)) {
483	      fastifyReply.status(statusCode);
484	    }
485	    if (body instanceof StreamableFile) {
486	      const streamHeaders = body.getHeaders();
487	      if (
488	        fastifyReply.getHeader('Content-Type') === undefined &&
489	        streamHeaders.type !== undefined
490	      ) {
491	        fastifyReply.header('Content-Type', streamHeaders.type);
492	      }
493	      if (
494	        fastifyReply.getHeader('Content-Disposition') === undefined &&
495	        streamHeaders.disposition !== undefined
496	      ) {
497	        fastifyReply.header('Content-Disposition', streamHeaders.disposition);
498	      }
499	      if (
500	        fastifyReply.getHeader('Content-Length') === undefined &&
501	        streamHeaders.length !== undefined
502	      ) {
503	        fastifyReply.header('Content-Length', streamHeaders.length);
504	      }
505	      body = body.getStream();
506	    }
507	    if (
508	      fastifyReply.getHeader('Content-Type') !== undefined &&
509	      fastifyReply.getHeader('Content-Type') !== 'application/json' &&
510	      body?.statusCode >= HttpStatus.BAD_REQUEST
511	    ) {
512	      Logger.warn(
513	        "Content-Type doesn't match Reply body, you might need a custom ExceptionFilter for non-JSON responses",
514	        FastifyAdapter.name,
515	      );
516	      fastifyReply.header('Content-Type', 'application/json');
517	    }
518	    return fastifyReply.send(body);
519	  }
