733	  public async createMiddlewareFactory(
734	    requestMethod: RequestMethod,
735	  ): Promise<(path: string, callback: Function) => any> {
736	    if (!this.isMiddieRegistered) {
737	      await this.registerMiddie();
738	    }
739	    return (path: string, callback: Function) => {
740	      const hasEndOfStringCharacter = path.endsWith('$');
741	      path = hasEndOfStringCharacter ? path.slice(0, -1) : path;
742	
743	      let normalizedPath = LegacyRouteConverter.tryConvert(path);
744	
745	      // Fallback to "*path" to support plugins like GraphQL
746	      normalizedPath = normalizedPath === '/*path' ? '*path' : normalizedPath;
747	
748	      // Normalize the path to support the prefix if it set in application
749	      if (
750	        this._pathPrefix &&
751	        !normalizedPath.startsWith(this._pathPrefix) &&
752	        (normalizedPath === '/' || normalizedPath === '')
753	      ) {
754	        normalizedPath = `${this._pathPrefix}${normalizedPath}`;
755	        if (normalizedPath.endsWith('/')) {
756	          normalizedPath = `${normalizedPath}{*path}`;
757	        }
758	      }
759	
760	      try {
761	        let { regexp: re } = pathToRegexp(normalizedPath);
762	        re = hasEndOfStringCharacter
763	          ? new RegExp(re.source + '$', re.flags)
764	          : re;
765	
766	        // The following type assertion is valid as we use import('@fastify/middie') rather than require('@fastify/middie')
767	        // ref https://github.com/fastify/middie/pull/55
768	        this.instance.use(
769	          normalizedPath,
770	          (req: any, res: any, next: Function) => {
771	            const queryParamsIndex = req.originalUrl.indexOf('?');
772	            let pathname =
773	              queryParamsIndex >= 0
774	                ? req.originalUrl.slice(0, queryParamsIndex)
775	                : req.originalUrl;
776	
777	            pathname = this.sanitizeUrl(pathname);
778	
779	            if (normalizedPath) {
780	              const pathToCheck = pathname.endsWith('/')
781	                ? pathname
782	                : `${pathname}/`;
783	              if (!re.exec(pathToCheck)) {
784	                return next();
785	              }
786	            }
787	            return callback(req, res, next);
788	          },
789	        );
790	      } catch (e) {
791	        if (e instanceof TypeError) {
792	          LegacyRouteConverter.printError(path);
793	        }
794	        throw e;
795	      }
796	    };
797	  }
