864	  /**
865	   * Installs a request gate in front of Fastify's routing so that, once the
866	   * shutdown has started, new requests are rejected with
867	   * "503 Service Unavailable" before they can enter the Nest pipeline
868	   * (middleware, guards, pipes, interceptors, handlers), while requests
869	   * that were already accepted run to completion.
870	   *
871	   * The gate has two layers:
872	   *
873	   * - a wrapper around the server's "request" listener, which rejects every
874	   *   request whose headers arrive after the shutdown started — including
875	   *   requests pipelined on an existing keep-alive connection. The listener
876	   *   is wrapped instead of using a Fastify "onRequest" hook because
877	   *   Fastify's own "return503OnClosing" fast path (enabled by default)
878	   *   runs before any hook and answers with a JSON body, which would not
879	   *   match the Express-compatible contract (a plain "Service Unavailable"
880	   *   body and a "Connection: close" header);
881	   * - a "preHandler" hook, which covers requests that were accepted by the
882	   *   first layer while the application was still running but have not
883	   *   reached a route handler yet when the shutdown starts — most notably
884	   *   requests whose body is still streaming in. Fastify runs "preHandler"
885	   *   hooks after the request body has been fully received and right before
886	   *   the route handler (where the Nest pipeline begins), so a late
887	   *   rejection here still happens before any guard, pipe, interceptor or
888	   *   controller runs and cannot trigger business side effects.
889	   */
890	  private installClosingRequestGate() {
891	    const server = this.httpServer as unknown as http.Server;
892	    const routing = this.instance.routing;
893	    server.removeListener('request', routing);
894	    server.on('request', (req, res) => {
895	      if (!this.isShuttingDown) {
896	        routing(req as unknown as TRawRequest, res as unknown as TRawResponse);
897	        return;
898	      }
899	      if (req.httpVersionMajor !== 2) {
900	        res.setHeader('Connection', 'close');
901	      }
902	      res.writeHead(HttpStatus.SERVICE_UNAVAILABLE, {
903	        'Content-Type': 'text/plain',
904	      });
905	      res.end('Service Unavailable');
906	    });
907	
908	    this.instance.addHook('preHandler', (request, reply, done) => {
909	      if (!this.isShuttingDown) {
910	        done();
911	        return;
912	      }
913	      if (request.raw.httpVersionMajor !== 2) {
914	        reply.header('Connection', 'close');
915	      }
916	      // Short-circuit the lifecycle without calling "done()".
917	      reply
918	        .code(HttpStatus.SERVICE_UNAVAILABLE)
919	        .header('Content-Type', 'text/plain')
920	        .send('Service Unavailable');
921	    });
922	
923	    this.installClosingUpgradeGate();
924	  }
925	
926	  /**
927	   * Installs an upgrade gate in front of every registered "upgrade" listener
928	   * (e.g. a "noServer" WebSocketServer) so that handshakes observed only after
929	   * the shutdown started are rejected at the HTTP layer, before the gateway
930	   * or any message handling can run: a plain "503 Service Unavailable"
931	   * response with "Connection: close", followed by socket termination.
932	   *
933	   * Upgrades observed while the application is still running - including ones
934	   * whose handshake bytes are still arriving when the shutdown begins - are
935	   * forwarded to the listeners registered at upgrade time, so already
936	   * accepted connections keep their existing error semantics and in-flight
937	   * work can drain. The server's "emit" is wrapped instead of registering an
938	   * "upgrade" listener so that listeners registered later (plugins attach
939	   * during application initialization, after the adapter) are covered as
940	   * well, and the gate stays the single interception point.
941	   */
942	  private installClosingUpgradeGate() {
943	    if (this.isClosingUpgradeGateInstalled) {
944	      return;
945	    }
946	    this.isClosingUpgradeGateInstalled = true;
947	
948	    const server = this.httpServer as unknown as http.Server;
949	    const originalEmit = server.emit.bind(server) as (
950	      event: string,
951	      ...args: any[]
952	    ) => boolean;
953	
954	    server.emit = ((event: string, ...args: any[]) => {
955	      if (event !== 'upgrade') {
956	        return originalEmit(event, ...args);
957	      }
958	
959	      const [request, socket, head] = args as [
960	        http.IncomingMessage,
961	        net.Socket,
962	        Buffer,
963	      ];
964	      if (!this.isShuttingDown) {
965	        return originalEmit('upgrade', request, socket, head);
966	      }
967	
968	      // Reject the handshake at the HTTP layer without dispatching it to any
969	      // upgrade listener (gateway/message handling never runs), then close the
970	      // underlying connection so it cannot be reused for further requests.
971	      if (!socket.writable) {
972	        socket.destroy();
973	        return false;
974	      }
975	      socket.once('error', () => socket.destroy());
976	      socket.end(
977	        [
978	          'HTTP/1.1 503 Service Unavailable',
979	          'Connection: close',
980	          'Content-Type: text/plain',
981	          'Content-Length: 19',
982	          '',
983	          'Service Unavailable',
984	        ].join('\r\n'),
985	      );
986	      return false;
987	    }) as typeof server.emit;
988	  }
