1037	  private injectRouteOptions(
1038	    routerMethodKey: Uppercase<HTTPMethods>,
1039	    ...args: any[]
1040	  ) {
1041	    const handlerRef = args[args.length - 1];
1042	    const isVersioned =
1043	      !isUndefined(handlerRef.version) &&
1044	      handlerRef.version !== VERSION_NEUTRAL;
1045	    const routeConfig = Reflect.getMetadata(
1046	      FASTIFY_ROUTE_CONFIG_METADATA,
1047	      handlerRef,
1048	    );
1049	
1050	    const routeConstraints = Reflect.getMetadata(
1051	      FASTIFY_ROUTE_CONSTRAINTS_METADATA,
1052	      handlerRef,
1053	    );
1054	
1055	    const routeSchema = Reflect.getMetadata(
1056	      FASTIFY_ROUTE_SCHEMA_METADATA,
1057	      handlerRef,
1058	    );
1059	
1060	    const hasConfig = !isUndefined(routeConfig);
1061	    const hasConstraints = !isUndefined(routeConstraints);
1062	    const hasSchema = !isUndefined(routeSchema);
1063	    const routeToInject: RouteOptions<TServer, TRawRequest, TRawResponse> &
1064	      RouteShorthandOptions = {
1065	      method: routerMethodKey,
1066	      url: args[0],
1067	      handler: handlerRef,
1068	    };
1069	
1070	    if (!this.instance.supportedMethods.includes(routerMethodKey)) {
1071	      this.instance.addHttpMethod(routerMethodKey, { hasBody: true });
1072	    }
1073	
1074	    if (isVersioned || hasConstraints || hasConfig || hasSchema) {
1075	      const isPathAndRouteTuple = args.length === 2;
1076	      if (isPathAndRouteTuple) {
1077	        const constraints = {
1078	          ...(hasConstraints && routeConstraints),
1079	          ...(isVersioned && {
1080	            version: handlerRef.version,
1081	          }),
1082	        };
1083	
1084	        const options = {
1085	          constraints,
1086	          ...(hasConfig && {
1087	            config: {
1088	              ...routeConfig,
1089	            },
1090	          }),
1091	          ...(hasSchema && {
1092	            schema: routeSchema,
1093	          }),
1094	        };
1095	
1096	        const routeToInjectWithOptions = { ...routeToInject, ...options };
1097	
1098	        return this.instance.route(routeToInjectWithOptions);
1099	      }
1100	    }
1101	    return this.instance.route(routeToInject);
1102	  }
1103	
1104	  /**
1105	   * Fastify still accepts the router options ("ignoreTrailingSlash",
1106	   * "caseSensitive", ...) at the top level, but "initialConfig.routerOptions"
1107	   * only reflects them when they are passed through "routerOptions". As the
1108	   * adapter always passes "routerOptions" (for the version constraint), the
1109	   * top-level values are folded in so that plugins relying on
1110	   * "initialConfig.routerOptions" (like @fastify/middie) normalize request
1111	   * paths exactly like the router does.
1112	   */
1113	  private getTopLevelRouterOptions(
1114	    options?: FastifyServerOptions,
1115	  ): NonNullable<FastifyServerOptions['routerOptions']> {
1116	    const routerOptions: Record<string, unknown> = {};
1117	    const routerOptionKeys = [
1118	      'ignoreTrailingSlash',
1119	      'ignoreDuplicateSlashes',
1120	      'caseSensitive',
1121	      'useSemicolonDelimiter',
1122	      'maxParamLength',
1123	      'allowUnsafeRegex',
1124	    ] as const;
1125	    for (const key of routerOptionKeys) {
1126	      if (options?.[key] !== undefined) {
1127	        routerOptions[key] = options[key];
1128	      }
1129	    }
1130	    return routerOptions;
1131	  }
1132	
1133	  private sanitizeUrl(url: string): string {
1134	    const initialConfig = this.instance.initialConfig as FastifyServerOptions;
1135	    const routerOptions =
1136	      initialConfig.routerOptions as Partial<FastifyServerOptions>;
1137	
1138	    // Absolute-form request targets ("GET http://host/path HTTP/1.1") must be
1139	    // resolved to their path before any other normalization, as the Fastify
1140	    // router does, so that middleware and routes always match the same path.
1141	    url = this.getPathFromRequestTarget(url);
1142	
1143	    if (
1144	      routerOptions.ignoreDuplicateSlashes ||
1145	      initialConfig.ignoreDuplicateSlashes
1146	    ) {
1147	      url = this.removeDuplicateSlashes(url);
1148	    }
1149	
1150	    if (
1151	      routerOptions.ignoreTrailingSlash ||
1152	      initialConfig.ignoreTrailingSlash
1153	    ) {
1154	      url = this.trimLastSlash(url);
1155	    }
1156	
1157	    if (
1158	      routerOptions.caseSensitive === false ||
1159	      initialConfig.caseSensitive === false
1160	    ) {
1161	      url = url.toLowerCase();
1162	    }
1163	    return safeDecodeURI(
1164	      url,
1165	      routerOptions.useSemicolonDelimiter ||
1166	        initialConfig.useSemicolonDelimiter,
1167	    ).path;
1168	  }
1169	
1170	  private removeDuplicateSlashes(path: string) {
1171	    const REMOVE_DUPLICATE_SLASHES_REGEXP = /\/\/+/g;
1172	    return path.indexOf('//') !== -1
1173	      ? path.replace(REMOVE_DUPLICATE_SLASHES_REGEXP, '/')
1174	      : path;
1175	  }
1176	
1177	  private trimLastSlash(path: string) {
1178	    if (path.length > 1 && path.charCodeAt(path.length - 1) === 47) {
1179	      return path.slice(0, -1);
1180	    }
1181	    return path;
1182	  }
1183	
1184	  /**
1185	   * Mirrors the absolute-form request target handling of "find-my-way".
1186	   * Returns the path of an absolute-form target ("http://host/path" -> "/path")
1187	   * and leaves any other request target untouched.
1188	   */
1189	  private getPathFromRequestTarget(url: string): string {
1190	    if (url.charCodeAt(0) === 47 /* '/' */) {
1191	      return url;
1192	    }
1193	    const schemeEnd = url.indexOf('://');
1194	    if (schemeEnd === -1) {
1195	      return url;
1196	    }
1197	    const scheme = url.slice(0, schemeEnd).toLowerCase();
1198	    if (scheme !== 'http' && scheme !== 'https') {
1199	      return url;
1200	    }
1201	    const authorityStart = schemeEnd + 3;
1202	    const pathStart = url.indexOf('/', authorityStart);
1203	    if (pathStart === authorityStart || !URL.canParse(url)) {
1204	      // Malformed target: the router rejects it before any middleware runs
1205	      return url;
1206	    }
1207	    return pathStart === -1 ? '/' : url.slice(pathStart);
1208	  }
1209	}
