private readonly middlewareModule: MiddlewareModule;
private readonly middlewareContainer = new MiddlewareContainer(
  this.container,
);
private microservicesModule: any = null;
private socketModule: any = null;
private readonly routesResolver: Resolver;
private readonly microservices: any[] = [];
private httpServer: any;
private isListening = false;
private isWsModuleRegistered = false;
/**
 * Whether a shutdown cycle has completed successfully. Afterwards the
 * closed instance cannot accept traffic anymore, so further "close()"
 * calls are no-ops instead of running the destroy/shutdown lifecycle hooks
 * (and cleanup) a second time.
 */
private isClosed = false;
/**
 * The shutdown cycle currently in flight, if any. Concurrent "close()"
 * callers await this very promise instead of starting a second teardown.
 */
private activeClosePromise?: Promise<void>;

/**
 * Runs the shutdown sequence behind "close()" (and the process signal
 * handlers). Concurrent calls share the first shutdown cycle, and once it
 * completed successfully further calls are no-ops: a closed instance
 * cannot serve traffic again, so the destroy/shutdown lifecycle hooks
 * (and their cleanup) must not run a second time. A shutdown that
 * rejected does not latch the guard, leaving the usual retry semantics
 * intact.
 */
protected shutdown(signal?: string): Promise<void> {
  if (this.isClosed) {
    return Promise.resolve();
  }
  this.activeClosePromise ??= super
    .shutdown(signal)
    .then(() => {
      this.isClosed = true;
    })
    .finally(() => {
      this.activeClosePromise = undefined;
    });
  return this.activeClosePromise;
}

constructor(
  container: NestContainer,
  private readonly httpAdapter: HttpServer,
  private readonly config: ApplicationConfig,
  private readonly graphInspector: GraphInspector,
  appOptions: NestApplicationOptions = {},
) {
  super(container, appOptions);

  this.config.setRouteConflictPolicy(appOptions.routeConflictPolicy);
  this.config.setRouteResolutionStrategy(appOptions.routeResolutionStrategy);
  this.selectContextModule();
  this.registerHttpServer();
  this.injector = new Injector({
    preview: this.appOptions.preview!,
    instanceDecorator: appOptions.instrument?.instanceDecorator,
  });
  this.middlewareModule = new MiddlewareModule();
  this.routesResolver = new RoutesResolver(
    this.container,
    this.config,
    this.injector,
    this.graphInspector,
  );
}

protected async prepareClose(): Promise<void> {
  this.httpAdapter && (await this.httpAdapter.beforeClose?.());
}

protected async dispose(): Promise<void> {
  await this.socketModule?.close();
  await this.microservicesModule?.close();
  await this.httpAdapter?.close();

  await Promise.all(
    iterate(this.microservices).map(async microservice => {
      microservice.setIsTerminated(true);
      await microservice.close();
    }),
  );
}

public getHttpAdapter(): AbstractHttpAdapter {
  return this.httpAdapter as AbstractHttpAdapter;
}

public registerHttpServer() {
  this.httpServer = this.createServer();
}

public getUnderlyingHttpServer<T>(): T {
  return this.httpAdapter.getHttpServer();
}

public applyOptions() {
  if (!this.appOptions || !this.appOptions.cors) {
    return undefined;
  }
  const passCustomOptions =
    isObject(this.appOptions.cors) || isFunction(this.appOptions.cors);
  if (!passCustomOptions) {
    return this.enableCors();
  }
  return this.enableCors(this.appOptions.cors);
}

public createServer<T = any>(): T {
  this.httpAdapter.initHttpServer(this.appOptions);
  return this.httpAdapter.getHttpServer() as T;
}

